    vector<int> v(n, 0);
    int mini = 0, maxi = 0;

    if (k != 0 && k != n) {
        mini = 1;

        int count = 0;
        for (int i = 1; i < n && count < k; i += 2) {
            v[i] = 1;
            count++;
        }

