            if (v[i] == 0) {
                v[i] = 1;
                count++;
            }
        }

        for (int i = 0; i < n; i++) {
            if (v[i] == 0 &&
                ((i > 0 && v[i - 1] == 1) ||
                 (i + 1 < n && v[i + 1] == 1))) {
                maxi++;
            }
        }
    }

    cout << mini << " " << maxi << '\n';
    return 0;
}

